'use client';

import { componentById, connections, hardware, pinById, type AssemblyConnection } from '@/lib/assembly-data';

type Props = {
  selectedConnectionId: string | null;
  onSelectConnection: (id: string) => void;
  activePinKeys: string[];
};

function pinPosition(componentId: AssemblyConnection['source']['componentId'], pinId: string) {
  const component = componentById(componentId); const pin = pinById(componentId, pinId);
  const x = pin.side === 'left' ? component.map.x - 8 : component.map.x + component.map.width + 8;
  const count = component.pins.filter((entry) => entry.side === pin.side).length;
  const y = component.map.y + ((pin.index + 1) * component.map.height) / (count + 1);
  return { x, y };
}

function pathFor(connection: AssemblyConnection, index: number) {
  const from = pinPosition(connection.source.componentId, connection.source.pinId);
  const to = pinPosition(connection.target.componentId, connection.target.pinId);
  const lift = 58 + index * 42;
  const middleY = Math.min(from.y, to.y) - lift;
  return `M ${from.x} ${from.y} C ${from.x + 70} ${middleY}, ${to.x - 70} ${middleY}, ${to.x} ${to.y}`;
}

export default function AssemblyBoard2D({ selectedConnectionId, onSelectConnection, activePinKeys }: Props) {
  const selected = connections.find((connection) => connection.id === selectedConnectionId);
  return <section className="assembly-board" aria-label="Vista superior da montagem">
    <div className="assembly-map-toolbar"><span><i className="status-dot" /> VISTA SUPERIOR · ESCALA RELATIVA</span><span>Arraste para ampliar no navegador · clique numa ligação ou terminal</span></div>
    <svg className="assembly-map" viewBox="0 0 1000 760" role="img" aria-label="Diagrama de montagem com terminais físicos e ligações pendentes">
      <defs>
        <filter id="connector-glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation="4" result="blur" /><feMerge><feMergeNode in="blur" /><feMergeNode in="SourceGraphic" /></feMerge></filter>
      </defs>
      <rect x="1" y="1" width="998" height="758" rx="16" className="map-surface" />
      <g className="map-grid">{Array.from({ length: 24 }, (_, index) => <line key={`v-${index}`} x1={index * 44} y1="0" x2={index * 44} y2="760" />)}{Array.from({ length: 19 }, (_, index) => <line key={`h-${index}`} x1="0" y1={index * 44} x2="1000" y2={index * 44} />)}</g>
      <g className="connection-layer">
        {connections.map((connection, index) => {
          const isSelected = connection.id === selectedConnectionId;
          const isDimmed = Boolean(selected && !isSelected);
          return <g key={connection.id} className={`map-connection ${isSelected ? 'selected' : ''} ${isDimmed ? 'dimmed' : ''}`} onClick={() => onSelectConnection(connection.id)}>
            <path d={pathFor(connection, index)} stroke={connection.color} />
            <path className="connection-hit" d={pathFor(connection, index)} />
          </g>;
        })}
      </g>
      {hardware.map((component) => <g key={component.id} className="map-component">
        <rect className="board-shadow" x={component.map.x + 7} y={component.map.y + 9} width={component.map.width} height={component.map.height} rx="10" />
        <rect className="board-body" x={component.map.x} y={component.map.y} width={component.map.width} height={component.map.height} rx="10" fill={component.boardColor} />
        <rect className="board-inset" x={component.map.x + 10} y={component.map.y + 10} width={component.map.width - 20} height={component.map.height - 20} rx="6" />
        <text className="board-name" x={component.map.x + component.map.width / 2} y={component.map.y + 30}>{component.shortName}</text>
        <text className="board-subtitle" x={component.map.x + component.map.width / 2} y={component.map.y + 49}>MODELO PARAMÉTRICO</text>
        {component.id === 'esp32' && <><rect className="usb-port" x={component.map.x + component.map.width / 2 - 32} y={component.map.y + component.map.height - 28} width="64" height="19" rx="4" /><rect className="chip" x={component.map.x + 55} y={component.map.y + 80} width="86" height="76" rx="4" /><text className="chip-text" x={component.map.x + 98} y={component.map.y + 122}>ESP32</text></>}
        {component.id === 'lora' && <><rect className="chip" x={component.map.x + 49} y={component.map.y + 91} width="86" height="91" rx="4" /><text className="chip-text" x={component.map.x + 92} y={component.map.y + 140}>SX1278</text><path className="antenna-2d" d={`M ${component.map.x + component.map.width / 2} ${component.map.y + 69} c -20 -16 20 -29 0 -43 c -20 -16 20 -29 0 -43 c -20 -16 20 -29 0 -43`} /></>}
        {component.id === 'sensor' && <><rect className="connector-2d" x={component.map.x + 28} y={component.map.y + 78} width="65" height="36" rx="5" /><circle className="trimpot-2d" cx={component.map.x + 112} cy={component.map.y + 166} r="20" /><rect className="chip" x={component.map.x + 45} y={component.map.y + 193} width="78" height="56" rx="4" /></>}
        {component.id === 'level' && <><rect className="chip" x={component.map.x + 53} y={component.map.y + 44} width="80" height="62" rx="4" /><text className="level-text" x={component.map.x + component.map.width / 2} y={component.map.y + 125}>HV ⇄ LV</text></>}
        {component.pins.map((pin) => { const position = pinPosition(component.id, pin.id); const key = `${component.id}:${pin.id}`; const active = activePinKeys.includes(key); return <g key={pin.id} className={`map-pin ${active ? 'active' : ''}`}><circle cx={position.x} cy={position.y} r="9" /><circle className="pin-hole" cx={position.x} cy={position.y} r="3.5" /><text x={pin.side === 'left' ? position.x - 15 : position.x + 15} y={position.y + 3} textAnchor={pin.side === 'left' ? 'end' : 'start'}>{pin.label}</text></g>; })}
      </g>)}
      {selected && <g className="selected-connection-callout"><rect x="306" y="680" width="390" height="54" rx="8" /><circle cx="328" cy="707" r="6" fill={selected.color} /><text x="345" y="703">{selected.signal}</text><text className="callout-detail" x="345" y="720">PENDENTE DE VALIDAÇÃO ELÉTRICA</text></g>}
    </svg>
  </section>;
}
